// Introductions for the notes and sheet music sections.
{
  const notes = 'I try to write these notes in a way that is most readable way, and tries to teach it to people. Please let me know if you find any errors, or a simpler/clearner arguments to some part.';
  const music = 'I wrote these music when I had a lot free time, now I am getting busier, but I will try to find time write more. The recording were done in piano back in school, and they were out of tune, but it should give a rough idea of how I was intending it to be played. They have not been named, I will think about what I should name them';
  const previousMusic = 'I wrote these music when I had a lot free time, now I am getting busier, but I will try to find time write more. The recording were done in piano back in school, and they were out of tune, but it should give a rough idea of how I was intending it to be played.';
  const additions = {
    fr: ['J’essaie d’écrire ces notes de la manière la plus lisible possible, afin de les enseigner à d’autres personnes. N’hésitez pas à me signaler toute erreur ou tout argument plus simple ou plus clair pour une partie de ces notes.', ' Ces morceaux n’ont pas encore de titre ; je réfléchirai aux noms à leur donner.'],
    ja: ['これらのノートは、できるだけ読みやすく、人に教えられるように書くことを心がけています。間違いや、ある部分についてもっと簡潔でわかりやすい議論があれば、ぜひ教えてください。', ' これらの曲にはまだ名前がありません。どんな名前をつけるか考えてみます。'],
    zh: ['我尽量以最易读的方式撰写这些笔记，希望它们能帮助大家学习。如果你发现任何错误，或者对某些部分有更简单、更清晰的论证，请告诉我。', '这些曲子还没有名字，我会想想该给它们取什么名字。'],
    'zh-Hant': ['我盡量以最易讀的方式撰寫這些筆記，希望它們能幫助大家學習。如果你發現任何錯誤，或者對某些部分有更簡單、更清晰的論證，請告訴我。', '這些曲子還沒有名字，我會想想該給它們取什麼名字。']
  };
  for (const [locale, [notesText, musicSuffix]] of Object.entries(additions)) {
    const dictionary = window.SITE_TRANSLATIONS[locale];
    dictionary[notes] = notesText;
    dictionary[music] = dictionary[previousMusic] + musicSuffix;
  }
}

